INSERT INTO `articles` (`id`, `title`, `title_en`, `slug`, `summary`, `summary_en`, `content`, `content_en`, `image_url`, `author_id`, `status`, `created_at`) VALUES
(1, 'Top 5 món đặc sản không thể bỏ lỡ khi đến Đắk Lắk', 'Top 5 Must-Try Specialties in Dak Lak', 'top-5-mon-dac-san-dak-lak', 'Khám phá ẩm thực Tây Nguyên qua những món ăn đậm chất núi rừng: Gà nướng bản Đôn, Bún đỏ, Gỏi lá, Rượu cần...', 'From grilled chicken with bamboo rice to red noodle soup, explore the unique flavors of the Central Highlands.', '<p>Đắk Lắk không chỉ nổi tiếng với những cánh rừng bạt ngàn, những ngọn thác hùng vĩ mà còn bởi nét văn hóa ẩm thực độc đáo. Dưới đây là 5 món đặc sản bạn nhất định phải thử khi đến vùng đất này:</p>\n                      <h3>1. Gà nướng Bản Đôn</h3>\n                      <p>Gà được nuôi thả rông trên đồi núi, thịt chắc và thơm. Gà sau khi làm sạch được tẩm ướp với muối ớt sả, mật ong rừng rồi nướng trên than hồng. Ăn kèm với cơm lam dẻo thơm thì không còn gì tuyệt vời bằng.</p>\n                      <h3>2. Bún đỏ Buôn Ma Thuột</h3>\n                      <p>Một tô bún đỏ rực rỡ với nước dùng ngọt thanh từ xương, cua đồng giã nhỏ, thịt băm, trứng cút... Sợi bún to, dai giòn, được nhuộm màu đỏ tự nhiên từ hạt điều, ăn cùng rau cần nước, cải ngọt luộc.</p>\n                      <h3>3. Gỏi lá</h3>\n                      <p>Món ăn là sự kết hợp của hơn 40 loại lá rừng khác nhau, cuộn cùng thịt ba chỉ luộc, tôm rang, da heo thái mỏng... Chấm cùng thứ nước chấm sền sệt đặc chế từ hèm rượu, trứng vịt, thịt băm.</p>\n                      <h3>4. Rượu cần</h3>\n                      <p>Thức uống truyền thống của đồng bào dân tộc thiểu số Tây Nguyên. Rượu được ủ men lá rừng, có vị ngọt nồng ấm, được uống trực tiếp từ chóe bằng những cần trúc dài.</p>\n                      <h3>5. Cà phê Buôn Ma Thuột</h3>\n                      <p>Tất nhiên, đến \"thủ phủ cà phê\" thì không thể bỏ qua một ly cà phê đậm đà, thơm lừng. Cà phê ở đây có hương vị đặc trưng, đánh thức mọi giác quan.</p>', 'Dak Lak is not only famous for its majestic nature but also for its rich and unique cuisine. Here are the must-try dishes:<br><br>1. **Grilled Chicken with Bamboo Rice (Cơm lam gà nướng):** A signature dish of the local people.<br>2. **Red Noodle Soup (Bún đỏ):** A popular street food in Buon Ma Thuot.<br>3. **Venison (Thịt nai):** A specialty often served as a gift.<br><br>Don\'t miss the chance to taste these amazing flavors!', '/travel_daklak/assets/images/uploads/article_1_food.png', 1, 'published', '2026-07-07 07:29:54'),
(2, 'Kinh nghiệm du lịch Bảo tàng Thế giới Cà phê 2024', 'Tips for Visiting The World Coffee Museum', 'kinh-nghiem-du-lich-bao-tang-the-gioi-ca-phe', 'Bảo tàng Thế giới Cà phê không chỉ là nơi lưu giữ lịch sử về cà phê mà còn là một kiệt tác kiến trúc độc đáo, điểm check-in cực \"hot\" tại Buôn Ma Thuột.', 'Everything you need to know before visiting this iconic architectural landmark.', '<p>Được mệnh danh là \"Châu Âu thu nhỏ giữa lòng Buôn Ma Thuột\", <strong>Bảo tàng Thế giới Cà phê</strong> là một điểm đến không thể bỏ qua đối với bất kỳ ai đặt chân đến Đắk Lắk.</p>\n                      <h3>Kiến trúc độc đáo</h3>\n                      <p>Bảo tàng có kiến trúc lấy cảm hứng từ không gian nhà dài truyền thống của đồng bào Tây Nguyên, kết hợp với những đường nét uốn lượn hiện đại. Không gian mở, đón ánh sáng tự nhiên, tạo cảm giác vô cùng thoáng đãng.</p>\n                      <h3>Khám phá lịch sử cà phê</h3>\n                      <p>Bên trong bảo tàng là không gian trưng bày hơn 10.000 hiện vật liên quan đến cà phê từ khắp nơi trên thế giới. Bạn sẽ được tìm hiểu về nguồn gốc, lịch sử, văn hóa cà phê qua các thời kỳ, cũng như quy trình sản xuất cà phê từ hạt đến ly.</p>\n                      <h3>Góc check-in \"triệu view\"</h3>\n                      <p>Mọi ngóc ngách trong bảo tàng đều có thể trở thành bối cảnh tuyệt vời cho những bức ảnh \"sống ảo\". Từ kiến trúc bên ngoài, không gian trưng bày bên trong, đến những quán cà phê mang phong cách hiện đại.</p>\n                      <p><strong>Lưu ý:</strong> Hãy chọn cho mình những trang phục vintage hoặc phong cách năng động để có những bức ảnh \"hợp cảnh\" nhất nhé!</p>', 'The World Coffee Museum is a must-visit spot. Here are some tips for your trip:<br><br>- **Best time to visit:** Early morning or late afternoon for the best lighting.<br>- **Tickets:** Buy tickets online or at the counter.<br>- **What to do:** Explore the exhibitions, taste the coffee, and take stunning photos with the unique architecture.<br><br>Enjoy your time in the coffee capital!', '/travel_daklak/assets/images/uploads/article_2_museum.png', 1, 'published', '2026-07-07 07:29:54'),
(3, 'Lịch trình 3 ngày 2 đêm phượt Đắk Lắk trọn vẹn', '3 Days 2 Nights Backpacking Itinerary in Dak Lak', 'lich-trinh-3-ngay-2-dem-phuot-dak-lak', 'Gợi ý lịch trình phượt Đắk Lắk 3 ngày 2 đêm chi tiết nhất, đi qua những địa điểm nổi tiếng: Hồ Lắk, Thác Dray Nur, Làng cà phê Trung Nguyên...', 'A detailed itinerary for a perfect weekend getaway in the Central Highlands.', '<p>Bạn đang lên kế hoạch phượt Đắk Lắk trong 3 ngày 2 đêm? Dưới đây là gợi ý lịch trình chi tiết giúp bạn khám phá trọn vẹn vẻ đẹp của vùng đất Tây Nguyên đầy nắng và gió.</p>\n                      <h3>Ngày 1: Khám phá thành phố Buôn Ma Thuột</h3>\n                      <ul>\n                          <li><strong>Sáng:</strong> Đến Buôn Ma Thuột, thưởng thức bún đỏ. Tham quan Bảo tàng Đắk Lắk, tìm hiểu văn hóa các dân tộc.</li>\n                          <li><strong>Chiều:</strong> Tham quan Làng cà phê Trung Nguyên, thưởng thức cà phê và check-in không gian kiến trúc độc đáo.</li>\n                          <li><strong>Tối:</strong> Dạo quanh Quảng trường 10/3, thưởng thức ẩm thực đường phố, mua sắm đồ lưu niệm.</li>\n                      </ul>\n                      <h3>Ngày 2: Chinh phục thác nước và khám phá Hồ Lắk</h3>\n                      <ul>\n                          <li><strong>Sáng:</strong> Di chuyển đến Thác Dray Nur - Dray Sap, chiêm ngưỡng vẻ đẹp hùng vĩ của dòng thác đổ. Tắm thác, tham gia các hoạt động trekking nhẹ nhàng.</li>\n                          <li><strong>Chiều:</strong> Di chuyển đến Hồ Lắk, hồ nước ngọt tự nhiên lớn thứ hai Việt Nam. Ngồi thuyền độc mộc ngắm cảnh hồ, cưỡi voi, thăm buôn làng của người M\'Nông.</li>\n                          <li><strong>Tối:</strong> Thưởng thức các món nướng ven hồ, thưởng thức rượu cần và hòa mình vào không gian văn hóa cồng chiêng.</li>\n                      </ul>\n                      <h3>Ngày 3: Khám phá Buôn Đôn và trở về</h3>\n                      <ul>\n                          <li><strong>Sáng:</strong> Đến Buôn Đôn, tham quan cầu treo thanh niên, nhà sàn cổ. Trải nghiệm cưỡi voi lội sông Sêrêpốk.</li>\n                          <li><strong>Trưa:</strong> Thưởng thức đặc sản Gà nướng Bản Đôn, cơm lam.</li>\n                          <li><strong>Chiều:</strong> Mua sắm đặc sản (cà phê, hạt tiêu, mật ong rừng...) làm quà. Kết thúc hành trình 3 ngày 2 đêm đầy thú vị.</li>\n                      </ul>\n                      <p><em>Lưu ý: Lịch trình có thể linh hoạt thay đổi tùy theo sở thích và điều kiện thời tiết thực tế.</em></p>', 'If you only have a weekend, here is the perfect itinerary:<br><br>- **Day 1:** Explore Buon Ma Thuot city, visit the Coffee Museum, and enjoy local food.<br>- **Day 2:** Visit Dray Nur and Dray Sap waterfalls, then head to Lak Lake for sunset.<br>- **Day 3:** Ride elephants in Buon Don and head back home.<br><br>Enjoy your trip!', '/travel_daklak/assets/images/uploads/article_3_waterfall.png', 1, 'published', '2026-07-07 07:29:54'),
(4, 'Cẩm nang du lịch Đắk Lắk toàn tập: Phương tiện, Ăn uống, Lưu trú & Trang phục', 'The Ultimate Dak Lak Travel Guide: Transport, Food, Accommodation & Clothing', 'cam-nang-du-lich-dak-lak-toan-tap', 'Gợi ý chi tiết nhất về phương tiện di chuyển, quán ăn đặc sản, homestay/khách sạn, trang phục và đồ lưu niệm cho chuyến du lịch Đắk Lắk của bạn.', 'A detailed guide on transportation, local food, homestays/hotels, clothing, and souvenirs for your trip to Dak Lak.', '<p>Đắk Lắk là một điểm đến tuyệt vời với vẻ đẹp hoang sơ của đại ngàn Tây Nguyên. Để chuyến đi của bạn thêm trọn vẹn, dưới đây là những thông tin chi tiết về phương tiện, ăn uống, lưu trú, trang phục và quà lưu niệm:</p>\n\n<h3>1. Phương tiện di chuyển</h3>\n<p><strong>Đến Đắk Lắk (Buôn Ma Thuột):</strong><br>\n- <strong>Máy bay:</strong> Nhanh chóng và tiện lợi nhất. Sân bay Buôn Ma Thuột có các chuyến bay thẳng từ TP.HCM, Hà Nội, Đà Nẵng, Hải Phòng.<br>\n- <strong>Xe khách:</strong> Đi xe giường nằm từ TP.HCM (khoảng 7-8 tiếng). Các nhà xe uy tín: Tiến Oanh, Kumho Samco, Mai Linh...<br>\n- <strong>Xe máy/Ô tô cá nhân:</strong> Dành cho những bạn thích phượt và ngắm cảnh dọc đường.</p>\n\n<p><strong>Di chuyển tại Đắk Lắk:</strong><br>\n- <strong>Thuê xe máy:</strong> Linh hoạt khám phá các ngõ ngách, buôn làng. Giá thuê khoảng 100.000 - 150.000 VNĐ/ngày.<br>\n- <strong>Taxi/Grab:</strong> Phù hợp đi lại trong trung tâm thành phố.</p>\n\n<h3>2. Gợi ý Quán ăn & Đặc sản</h3>\n<ul>\n    <li><strong>Bún đỏ:</strong> Đặc sản trứ danh với sợi bún to, nước dùng màu đỏ từ hạt điều. <em>(Gợi ý: Bún đỏ cô Thu, Bún đỏ Thúy)</em></li>\n    <li><strong>Gà nướng - Cơm lam:</strong> Gà thả rông nướng ống tre chấm muối sả. <em>(Gợi ý: Khu du lịch sinh thái Buôn Đôn, Quán Cà Te)</em></li>\n    <li><strong>Phở hai tô (Phở khô Tây Nguyên):</strong> <em>(Gợi ý: Phở khô 52, Phở Tiến)</em></li>\n    <li><strong>Cà phê:</strong> Không thể thiếu khi đến thủ phủ cà phê. <em>(Gợi ý: Làng cà phê Trung Nguyên, Arul Coffee, SOUL Roastery)</em></li>\n</ul>\n\n<h3>3. Homestay & Khách sạn</h3>\n<p>Tùy vào sở thích và ngân sách, bạn có thể chọn:<br>\n- <strong>Homestay view thiên nhiên:</strong> Lee\'s House (\"Bali thu nhỏ\"), Zan Homestay, Lak Tented Camp, The Highland House.<br>\n- <strong>Khách sạn trung tâm:</strong> Mường Thanh Luxury Buôn Ma Thuột, Elephants Hotel, Hai Ba Trung Hotel.</p>\n\n<h3>4. Gợi ý Trang phục</h3>\n<p>- <strong>Ban ngày:</strong> Quần áo năng động, thoải mái. <strong>Bắt buộc mang giày thể thao</strong> để đi thác, đi rừng.<br>\n- <strong>Buổi tối:</strong> Mang theo <strong>áo khoác mỏng</strong> hoặc cardigan vì trời sẽ se lạnh.<br>\n- <strong>Chụp ảnh sống ảo:</strong> Trang phục Vintage, Bohemian (Boho) màu sắc sặc sỡ, hoặc thuê trang phục truyền thống của người đồng bào tại các điểm du lịch.</p>\n\n<h3>5. Quà lưu niệm</h3>\n<p>- <strong>Cà phê:</strong> Món quà ý nghĩa và thiết thực nhất.<br>\n- <strong>Đặc sản:</strong> Thịt nai khô, hạt mắc ca, hạt điều, mật ong hoa cà phê.<br>\n- <strong>Đồ thổ cẩm:</strong> Túi xách, ví, khăn choàng dệt thủ công của người Ê-đê, M\'Nông.</p>', '<p>Dak Lak is a wonderful destination with the wild beauty of the Central Highlands. To make your trip perfect, here is detailed information on transportation, food, accommodation, clothing, and souvenirs:</p>\n\n<h3>1. Transportation</h3>\n<p><strong>Getting to Dak Lak (Buon Ma Thuot):</strong><br>\n- <strong>Flights:</strong> The fastest and most convenient. Buon Ma Thuot Airport has direct flights from HCMC, Hanoi, Da Nang, and Hai Phong.<br>\n- <strong>Sleeper Buses:</strong> From HCMC (about 7-8 hours). Reputable companies: Tien Oanh, Kumho Samco, Mai Linh...<br>\n- <strong>Motorbike/Private Car:</strong> For backpackers who love scenic road trips.</p>\n\n<p><strong>Getting around Dak Lak:</strong><br>\n- <strong>Motorbike rental:</strong> Flexible for exploring villages. Price is around 100,000 - 150,000 VND/day.<br>\n- <strong>Taxi/Grab:</strong> Suitable for moving around the city center.</p>\n\n<h3>2. Food & Specialties</h3>\n<ul>\n    <li><strong>Red Noodle Soup (Bun do):</strong> A famous specialty with large noodles and cashew-colored broth.</li>\n    <li><strong>Grilled Chicken & Bamboo Rice:</strong> Free-range chicken grilled in bamboo tubes.</li>\n    <li><strong>Two-bowl Pho (Central Highlands dry Pho)</strong></li>\n    <li><strong>Coffee:</strong> A must-try in the coffee capital. <em>(Suggestions: Trung Nguyen Coffee Village, Arul Coffee, SOUL Roastery)</em></li>\n</ul>\n\n<h3>3. Homestays & Hotels</h3>\n<p>- <strong>Nature-view Homestays:</strong> Lee\'s House (a \"mini Bali\"), Zan Homestay, Lak Tented Camp, The Highland House.<br>\n- <strong>City Center Hotels:</strong> Muong Thanh Luxury Buon Ma Thuot, Elephants Hotel, Hai Ba Trung Hotel.</p>\n\n<h3>4. Clothing Tips</h3>\n<p>- <strong>Daytime:</strong> Comfortable and active clothes. <strong>Sports shoes are a must</strong> for hiking and visiting waterfalls.<br>\n- <strong>Evening:</strong> Bring a <strong>light jacket</strong> or cardigan as it gets chilly at night.<br>\n- <strong>Photography:</strong> Colorful Vintage or Bohemian outfits, or rent traditional ethnic costumes at tourist spots.</p>\n\n<h3>5. Souvenirs</h3>\n<p>- <strong>Coffee:</strong> The most meaningful and practical gift.<br>\n- <strong>Local products:</strong> Dried venison, macadamia nuts, cashew nuts, coffee flower honey.<br>\n- <strong>Brocade items:</strong> Hand-woven bags, wallets, and scarves by the E De and M\'nong people.</p>', '/travel_daklak/assets/images/article_4_guide.png', 1, 'published', '2026-07-16 04:54:52');
