INSERT INTO `destinations` (`id`, `category_id`, `name`, `name_en`, `slug`, `short_desc`, `short_desc_en`, `description`, `description_en`, `address`, `image_url`, `image_360_url`, `avg_visit_hours`, `price_level`, `rating`, `latitude`, `longitude`, `virtual_tour_enabled`, `virtual_tour_type`, `audio_guide_url`, `tags`, `created_at`) VALUES
(1, 2, 'Hồ Lắk', 'Lak Lake', 'ho-lak', 'Hồ nước ngọt tự nhiên lớn thứ 2 Việt Nam, gắn với văn hoá M\'nông.', 'The 2nd largest natural freshwater lake in Vietnam, deeply connected to M\'nong culture.', 'Hồ Lắk là một trong những hồ nước ngọt tự nhiên lớn nhất Việt Nam, nằm tại huyện Lắk, tỉnh Đắk Lắk. Du khách có thể đi thuyền độc mộc, cưỡi voi, tham quan Biệt điện Bảo Đại và trải nghiệm văn hoá người M\'nông quanh hồ.', 'Lak Lake is a famous eco-tourism destination in Dak Lak. Visitors can experience dugout canoe rides, admire the sunset on the lake, and explore the traditional longhouses of the M\'nong people.', 'Huyện Lắk, Đắk Lắk', 'https://nhanghitaynguyen.com/wp-content/uploads/2020/09/tham-quan-ho-lak.jpg', '/assets/images/360/lake.png', 3.0, 'low', 5.0, 12.420300, 108.185400, 1, 'pannellum', NULL, 'thiên nhiên,hồ,văn hoá,thuyền độc mộc', '2026-06-28 05:57:43'),
(2, 1, 'Thác Dray Nur', 'Dray Nur Waterfall', 'thac-dray-nur', 'Một trong những thác nước hùng vĩ nhất Tây Nguyên.', 'One of the most majestic waterfalls in the Central Highlands.', 'Thác Dray Nur nằm trên dòng sông Sêrêpốk, là một trong những thác nước đẹp và hùng vĩ nhất khu vực Tây Nguyên, thích hợp cho trekking, chụp ảnh và tắm thác.', 'Dray Nur waterfall is breathtakingly beautiful with its massive curtain of water. You can explore the mysterious cave behind the waterfall and enjoy the pristine nature.', 'Huyện Krông Ana, Đắk Lắk', 'https://trungnguyenhealing.com/resources/uploads/Dray%20-Nur.jpg', '/assets/images/360/waterfall.png', 2.5, 'low', 5.0, 12.566700, 108.116700, 1, 'pannellum', NULL, 'thiên nhiên,thác nước,trekking', '2026-06-28 05:57:43'),
(3, 1, 'Thác Dray Sáp', 'Dray Sap Waterfall', 'thac-dray-sap', 'Thác \"nước khói\" nổi tiếng gần Buôn Ma Thuột.', 'The famous \'smoke waterfall\' near Buon Ma Thuot.', 'Thác Dray Sáp (nghĩa là \"thác khói\") nổi tiếng với dòng nước tung bọt trắng như sương khói, gần khu vực Dray Nur, thuận tiện kết hợp tham quan trong cùng ngày.', 'Located near Dray Nur, Dray Sap is known for the mist that rises from the falling water, creating a mystical atmosphere in the middle of the jungle.', 'Huyện Krông Ana, Đắk Lắk', 'https://ticotravel.com.vn/wp-content/uploads/2022/10/Thac-Dray-Sap-5.jpg', '/assets/images/360/draysap.png', 2.0, 'low', 4.5, 12.572800, 108.108300, 1, 'pannellum', NULL, 'thiên nhiên,thác nước', '2026-06-28 05:57:43'),
(4, 3, 'Buôn Đôn', 'Buon Don', 'buon-don', 'Làng văn hoá nổi tiếng với nghề săn bắt và thuần dưỡng voi.', 'Famous for its elephant taming tradition and the suspension bridge over Serepok river.', 'Buôn Đôn là điểm đến văn hoá nổi tiếng của Đắk Lắk, nơi du khách tìm hiểu về nghề thuần dưỡng voi, tham quan nhà dài truyền thống, cầu treo và mộ vua voi Khunjunob.', 'Experience the wild nature, walk on the long suspension bridge, and learn about the unique culture of the local ethnic minorities.', 'Huyện Buôn Đôn, Đắk Lắk', 'https://ik.imagekit.io/tvlk/blog/2023/05/buon-don-1.jpg?tr=dpr-2,w-675', '/assets/images/360/buondon.png', 3.0, 'medium', 4.4, 13.016700, 107.833300, 1, 'pannellum', NULL, 'văn hoá,voi,nhà dài,cầu treo', '2026-06-28 05:57:43'),
(5, 4, 'Vườn quốc gia Yok Đôn', 'Yok Don National Park', 'vuon-quoc-gia-yok-don', 'Vườn quốc gia lớn nhất Việt Nam, nơi sinh sống của voi rừng.', 'The only national park in Vietnam that preserves the dipterocarp forest ecosystem.', 'Yok Đôn là vườn quốc gia lớn nhất Việt Nam, nổi bật với hệ sinh thái rừng khô đặc trưng Tây Nguyên và là nơi triển khai mô hình du lịch thân thiện với voi (không cưỡi voi).', 'A paradise for nature lovers. You can join trekking tours, go bird watching, and see the ethical elephant tours where elephants roam freely.', 'Huyện Buôn Đôn, Đắk Lắk', 'https://luhanhvietnam.com.vn/du-lich/vnt_upload/news/04_2020/vuon-quoc-gia-yok-don.jpg', '/assets/images/360/yokdon.png', 4.0, 'medium', 4.5, 13.083300, 107.783300, 1, 'pannellum', NULL, 'thiên nhiên,rừng,voi,sinh thái', '2026-06-28 05:57:43'),
(6, 5, 'Cà phê Buôn Ma Thuột', 'Buon Ma Thuot Coffee', 'ca-phe-buon-ma-thuot', 'Thủ phủ cà phê Việt Nam, trải nghiệm văn hoá cà phê đặc sắc.', 'The coffee capital of Vietnam, a great place to experience the culture of roasted coffee.', 'Buôn Ma Thuột được mệnh danh là \"thủ phủ cà phê\" của Việt Nam. Du khách có thể tham quan các đồn điền cà phê, Bảo tàng Thế giới Cà phê và thưởng thức cà phê nguyên chất Đắk Lắk.', 'A must-visit for coffee lovers. You can learn about the history of coffee, admire unique architecture, and taste premium coffee blends.', 'TP. Buôn Ma Thuột, Đắk Lắk', 'https://th.bing.com/th/id/R.e44b2f35f39e2f95124b573a71df1395?rik=lad4Uf7u8%2fjhJQ&pid=ImgRaw&r=0', '/assets/images/360/coffee.png', 2.0, 'free', 4.6, 12.666700, 108.050000, 1, 'pannellum', NULL, 'ẩm thực,cà phê,bảo tàng', '2026-06-28 05:57:43'),
(7, 3, 'Buôn Akô Dhông', 'Ako Dhong Village', 'buon-ako-dhong', 'Buôn làng Ê Đê đẹp nhất Buôn Ma Thuột.', 'A peaceful E De village in the heart of Buon Ma Thuot city.', 'Buôn Akô Dhông nằm ngay trong lòng thành phố Buôn Ma Thuột, nổi tiếng với những ngôi nhà dài truyền thống của người Ê Đê và không gian xanh yên bình.', 'Ako Dhong is known for its beautiful traditional longhouses, peaceful atmosphere, and the rich cultural heritage of the E De people.', 'TP. Buôn Ma Thuột, Đắk Lắk', 'https://52hz.vn/wp-content/uploads/2021/12/1-buon-ako-dhong.jpg', '/assets/images/360/akodhong.png', 1.5, 'free', 4.3, 12.683300, 108.033300, 1, 'pannellum', NULL, 'văn hoá,nhà dài,Ê Đê', '2026-06-28 05:57:43'),
(8, 2, 'Hồ Ea Kao', 'Ea Kao Lake', 'ho-ea-kao', 'Hồ nước rộng lớn gần trung tâm thành phố, thích hợp cắm trại.', 'A serene lake surrounded by green forests, perfect for picnics and sunset watching.', 'Hồ Ea Kao là hồ nhân tạo rộng lớn nằm gần TP. Buôn Ma Thuột, không khí mát mẻ, phù hợp cho dã ngoại, cắm trại và chụp ảnh.', 'Ea Kao Lake is a great place to relax, enjoy the fresh air, and watch the beautiful sunset over the water.', 'TP. Buôn Ma Thuột, Đắk Lắk', 'https://images.unsplash.com/photo-1501785888041-af3ef285b470?q=80&w=1740&auto=format&fit=crop', '/assets/images/360/eakao.png', 2.0, 'free', 4.2, 12.616700, 108.083300, 1, 'pannellum', NULL, 'thiên nhiên,hồ,cắm trại', '2026-06-28 05:57:43'),
(9, 1, 'Gành Đá Đĩa - Phú Yên', 'Ganh Da Dia - Phu Yen', 'ganh-da-dia-phu-yen', 'Kiệt tác thiên nhiên với các khối đá hình lăng trụ xếp liền nhau.', 'A natural masterpiece with interlocking basalt columns.', 'Gành Đá Đĩa là một trong những danh thắng quốc gia đặc biệt của Phú Yên, thu hút đông đảo du khách bởi cấu tạo địa chất độc đáo. Các khối đá bazan hình lục giác, ngũ giác xếp chồng lên nhau như những chồng đĩa vươn ra biển.', 'Ganh Da Dia is a unique geological phenomenon in Vietnam. It looks like a giant black honeycomb rising from the sea, a must-visit destination in Phu Yen.', NULL, 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcT4cQHVjy3FlG4S5vT8U6X2ODZhfuFUWxnesG4pdjggEQ&s=10', NULL, 3.0, 'low', 4.5, 13.344400, 109.297500, 1, 'pannellum', NULL, 'biển, thiên nhiên, phú yên, chụp ảnh', '2026-07-16 05:31:25'),
(10, 3, 'Đầm Ô Loan', 'O Loan Lagoon', 'dam-o-loan-phu-yen', 'Đầm nước lợ nổi tiếng với đặc sản sò huyết ngon nức tiếng.', 'A brackish lagoon famous for its delicious blood cockles.', 'Nằm yên bình dưới chân đèo Quán Cau, Đầm Ô Loan mang vẻ đẹp tĩnh lặng, thơ mộng. Nơi đây là điểm đến lý tưởng để ngắm hoàng hôn và thưởng thức hải sản tươi sống, đặc biệt là sò huyết.', 'O Loan Lagoon offers a peaceful scenery, especially at sunrise or sunset. Don\'t forget to try the famous seafood here, especially the blood cockles.', NULL, 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSEBdZft0ylOuzK427c9NrL6tM3F1LaljtvagMAz4VIDQ&s=10', NULL, 2.0, 'medium', 4.5, 13.279200, 109.255800, 1, 'pannellum', NULL, 'hải sản, thiên nhiên, phú yên, ẩm thực', '2026-07-16 05:31:25'),
(11, 1, 'Vịnh Vũng Rô', 'Vung Ro Bay', 'vinh-vung-ro', 'Vịnh biển xanh biếc, lịch sử hào hùng và hải sản phong phú.', 'A blue bay with a heroic history and abundant seafood.', 'Vũng Rô là một vịnh nhỏ thuộc xã Hòa Xuân Nam, huyện Đông Hòa. Nơi đây từng là bến đỗ của những con tàu Không số trong chiến tranh. Ngày nay, Vũng Rô níu chân du khách bởi làn nước trong xanh và các bè hải sản tươi ngon.', 'Vung Ro Bay is surrounded by high mountains. It was an important site for the Ho Chi Minh trail on the sea during the war, and now a beautiful spot for tourists.', NULL, 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcTspxuPrmvTfEI-3LqlNcQlp8A-Dy3ZqcqJ1WsH0jAxwg&s=10', NULL, 4.0, 'medium', 4.5, 12.871400, 109.390800, 1, 'pannellum', NULL, 'biển, lịch sử, phú yên, hải sản', '2026-07-16 05:31:25'),
(12, 1, 'Bãi Môn - Mũi Điện', 'Bai Mon - Mui Dien', 'bai-mon-mui-dien', 'Nơi đón bình minh đầu tiên trên đất liền Việt Nam.', 'The easternmost point of Vietnam, welcoming the first sunrise.', 'Mũi Điện (Mũi Đại Lãnh) và Bãi Môn tạo nên một bức tranh tuyệt đẹp. Dưới chân ngọn hải đăng là bãi cát trắng mịn và làn nước trong vắt. Trải nghiệm cắm trại và đón những tia nắng đầu tiên là không thể bỏ lỡ.', 'Mui Dien Cape features a historic lighthouse and the beautiful, pristine Bai Mon beach. It is one of the places to catch the first rays of the sun in Vietnam.', NULL, 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQWP_jhWbLpoMC4h1nZFbMp_0N-mf_Va-R2WqO3raYZbA&s=10', NULL, 3.0, 'low', 4.5, 12.877200, 109.431900, 1, 'pannellum', NULL, 'biển, bình minh, thiên nhiên, phú yên', '2026-07-16 05:31:25'),
(13, 2, 'Tháp Nghinh Phong', 'Nghinh Phong Tower', 'thap-nghinh-phong', 'Biểu tượng du lịch mới của thành phố Tuy Hòa, Phú Yên.', 'The new tourism symbol of Tuy Hoa city, Phu Yen.', 'Tháp Nghinh Phong được thiết kế lấy cảm hứng từ truyền thuyết Lạc Long Quân - Âu Cơ, mang kiến trúc độc đáo, là điểm check-in không thể bỏ qua khi đến Phú Yên.', 'Inspired by the legend of Lac Long Quan and Au Co, Nghinh Phong Tower features unique architecture and is a must-visit check-in spot when visiting Phu Yen.', 'Tuy Hòa, Phú Yên', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQEhQVn4p38sAF0DcaBdoyGwrFBhw2cDDzGx2CBUQGyUA&s=10', NULL, 1.5, 'free', 4.5, 13.084700, 109.324500, 1, 'pannellum', NULL, '', '2026-07-16 06:06:49'),
(14, 1, 'Hòn Yến', 'Hon Yen', 'hon-yen-phu-yen', 'Hòn đảo nhỏ với rạn san hô tuyệt đẹp lộ trên mặt nước lúc thủy triều rút.', 'A small island with beautiful coral reefs exposed at low tide.', 'Hòn Yến mang vẻ đẹp hoang sơ. Vào những ngày đầu hoặc giữa tháng âm lịch, khi thủy triều rút xuống, nơi đây để lộ ra những rạn san hô nhiều màu sắc vô cùng rực rỡ.', 'Hon Yen retains its pristine beauty. During the beginning or middle of the lunar month, the low tide reveals incredibly vibrant coral reefs.', 'Tuy An, Phú Yên', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcS9iFa7pm2jVGyUbinnJAq7Hxy8ji-aQDIxFFU0oP2rIw&s=10', NULL, 2.5, 'low', 4.5, 13.238400, 109.305600, 1, 'pannellum', NULL, '', '2026-07-16 06:06:49'),
(15, 1, 'Thác Thủy Tiên', 'Thuy Tien Waterfall', 'thac-thuy-tien-dak-lak', 'Tuyệt tác thiên nhiên ba tầng giữa chốn đại ngàn Krông Năng.', 'A natural masterpiece with three levels in Krong Nang forest.', 'Thác Thủy Tiên (hay còn gọi là thác Ba Tầng) có không gian rộng lớn, hoang sơ và mát mẻ, phù hợp cho các chuyến dã ngoại, tắm suối và khám phá rừng núi.', 'Thuy Tien Waterfall (also known as Three-Level Waterfall) has a spacious, pristine, and cool environment, perfect for picnics, stream bathing, and forest exploration.', 'Krông Năng, Đắk Lắk', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSxl35MlOu-moY33HONtFVWrecehXE9nDHLJ5bdlTKbjA&s=10', NULL, 3.0, 'low', 5.0, 12.969100, 108.337100, 1, 'pannellum', NULL, '', '2026-07-16 06:06:49'),
(16, 1, 'Núi Đá Voi Mẹ', 'Mother Elephant Rock', 'nui-da-voi-me', 'Tảng đá nguyên khối lớn nhất Việt Nam mang truyền thuyết kỳ bí.', 'Vietnam\'s largest monolithic rock with mysterious legends.', 'Núi Đá Voi Mẹ là một khối đá granite khổng lồ hình dáng như con voi đang nằm. Du khách có thể leo lên đỉnh để ngắm nhìn toàn cảnh hồ Lắk và rừng nguyên sinh.', 'Mother Elephant Rock is a massive granite block shaped like a lying elephant. Tourists can climb to the top to enjoy a panoramic view of Lak Lake and the primary forest.', 'Lắk, Đắk Lắk', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRl0t9_b8mayyr3mZz2ZwYOIaS1SStDFRDxHJUWVawjew&s=10', NULL, 1.5, 'free', 4.5, 12.441100, 108.199100, 1, 'pannellum', NULL, '', '2026-07-16 06:06:49');
INSERT INTO `itineraries` (`id`, `user_id`, `title`, `days`, `preferences`, `ai_raw_response`, `created_at`) VALUES
(4, 2, 'Lịch trình 2 ngày - văn hoá, ẩm thực', 2, 'văn hoá, ẩm thực', '{\n  \"itinerary\": [\n    {\n      \"day\": 1,\n      \"title\": \"Khám phá văn hoá và ẩm thực phố núi Buôn Ma Thuột\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"activity\": \"Thưởng thức Cà phê Buôn Ma Thuột tại thủ phủ cà phê, tìm hiểu về văn hóa cà phê bản địa và dùng bữa sáng với món bún đỏ đặc sản.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng xe máy hoặc taxi trong khu vực trung tâm thành phố Buôn Ma Thuột.\",\n          \"price\": \"40.000 - 80.000 VNĐ/người\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"activity\": \"Ăn trưa với các món ăn truyền thống của người Ê Đê như vếch bò, gà nướng bản địa.\",\n          \"address\": \"\",\n          \"transport\": \"Đi bộ hoặc đi xe máy khoảng 5-10 phút từ quán cà phê trung tâm.\",\n          \"price\": \"150.000 - 250.000 VNĐ/người\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"activity\": \"Ghé thăm Buôn Akô Dhông để chiêm ngưỡng những ngôi nhà dài truyền thống của người Ê Đê và tìm hiểu đời sống văn hóa đặc sắc nơi đây.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng xe máy hoặc ô tô khoảng 3km từ trung tâm thành phố.\",\n          \"price\": \"Miễn phí (vé vào buôn tự do, chi phí mua sắm/nước uống tự túc khoảng 30.000 - 50.000 VNĐ)\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"activity\": \"Thư giãn, ngắm hoàng hôn và dạo mát tại Hồ Ea Kao, sau đó thưởng thức ẩm thực đường phố quanh hồ.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng xe máy hoặc taxi khoảng 20 phút (~12km) từ Buôn Akô Dhông.\",\n          \"price\": \"50.000 - 100.000 VNĐ/người (chi phí ăn vặt và nước uống)\"\n        }\n      ]\n    },\n    {\n      \"day\": 2,\n      \"title\": \"Trải nghiệm văn hóa M\'nông và thiên nhiên hùng vĩ\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"activity\": \"Khám phá Hồ Lắk, trải nghiệm đi thuyền độc mộc trên hồ nước ngọt tự nhiên lớn thứ hai Việt Nam và tìm hiểu văn hoá của người M\'nông Gar.\",\n          \"address\": \"Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng ô tô hoặc xe máy từ trung tâm TP. Buôn Ma Thuột đi theo quốc lộ 27 khoảng 1 giờ 15 phút (~56km).\",\n          \"price\": \"150.000 - 200.000 VNĐ/người (bao gồm vé thuê thuyền độc mộc)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"activity\": \"Thưởng thức bữa trưa với các món đặc sản Hồ Lắk như chả cá thát lát, cá bống kho tộ.\",\n          \"address\": \"Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Đi bộ từ khu vực ven hồ đến các nhà hàng ẩm thực lân cận.\",\n          \"price\": \"120.000 - 200.000 VNĐ/người\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"activity\": \"Di chuyển tham quan Thác Dray Nur, chiêm ngưỡng sự hùng vĩ của một trong những thác nước đẹp nhất Tây Nguyên và chụp ảnh lưu niệm.\",\n          \"address\": \"Huyện Krông Ana, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng ô tô hoặc xe máy khoảng 1 giờ 30 phút (~60km) từ Hồ Lắk theo hướng về Krông Ana.\",\n          \"price\": \"30.000 VNĐ/người (vé vào cổng thác)\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"activity\": \"Trở về Buôn Ma Thuột, ăn tối nhẹ nhàng với món bánh ướt chồng dĩa đặc sản và mua sắm quà lưu niệm, cà phê trước khi kết thúc hành trình.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Di chuyển khoảng 45 phút (~30km) từ Thác Dray Nur về lại trung tâm TP. Buôn Ma Thuột.\",\n          \"price\": \"50.000 - 100.000 VNĐ/người\"\n        }\n      ]\n    }\n  ]\n}', '2026-07-06 07:39:09'),
(5, 2, 'Lịch trình 2 ngày - văn hoá, trekking, gia đình', 2, 'văn hoá, trekking, gia đình', '{\n  \"itinerary\": [\n    {\n      \"day\": 1,\n      \"title\": \"Hành trình Văn hoá Ê Đê và Hương vị Cao nguyên\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"activity\": \"Khởi đầu ngày mới tại TP. Buôn Ma Thuột bằng việc thưởng thức Cà phê Buôn Ma Thuột, tìm hiểu về lịch sử và văn hoá cà phê của thủ phủ Tây Nguyên.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng xe máy hoặc taxi trong khu vực nội thành TP. Buôn Ma Thuột.\",\n          \"price\": \"40.000 - 100.000 VNĐ/người (chi phí đồ uống và ăn sáng nhẹ)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"activity\": \"Ghé thăm Buôn Akô Dhông để chiêm ngưỡng những ngôi nhà dài truyền thống của người Ê Đê, tìm hiểu văn hóa bản địa và dùng bữa trưa với các món ăn đặc sản Tây Nguyên.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng ô tô hoặc xe máy khoảng 10 phút (~3km) từ trung tâm thành phố.\",\n          \"price\": \"150.000 - 250.000 VNĐ/người (miễn phí vé vào buôn, chi phí ăn trưa ẩm thực bản địa)\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"activity\": \"Thư giãn và dạo chơi tại Hồ Ea Kao, ngắm cảnh hoàng hôn yên bình, thích hợp cho các hoạt động gia đình và chụp ảnh lưu niệm.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng ô tô hoặc xe máy khoảng 20 phút (~9km) về hướng Đông Nam từ Buôn Akô Dhông.\",\n          \"price\": \"30.000 - 50.000 VNĐ/người (chi phí nước uống hoặc thuê bạt ngắm cảnh)\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"activity\": \"Trở về trung tâm thành phố ăn tối, tự do dạo phố đêm Buôn Ma Thuột và thưởng thức các món ăn đường phố.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng taxi hoặc xe máy cá nhân.\",\n          \"price\": \"100.000 - 150.000 VNĐ/người (chi phí ăn tối tự túc)\"\n        }\n      ]\n    },\n    {\n      \"day\": 2,\n      \"title\": \"Trekking Hùng Vĩ và Trải nghiệm Thác Nguồn\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"activity\": \"Hành trình trekking, khám phá vẻ đẹp hoang sơ và kỳ vĩ của Thác Dray Nur. Gia đình có thể đi dạo trên các lối mòn, chụp ảnh check-in và cảm nhận hơi nước mát lạnh.\",\n          \"address\": \"Huyện Krông Ana, Đắk Lắk\",\n          \"transport\": \"Thuê ô tô tự lái hoặc xe máy di chuyển khoảng 50 phút (~30km) từ trung tâm TP. Buôn Ma Thuột theo hướng quốc lộ 14 rẽ đường tỉnh 682.\",\n          \"price\": \"50.000 VNĐ/người (vé vào cổng tham quan thác)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"activity\": \"Thưởng thức bữa trưa dã ngoại hoặc dùng bữa tại nhà hàng ngay cạnh Thác Dray Nur với các món đặc sản như cơm lam, gà nướng.\",\n          \"address\": \"Huyện Krông Ana, Đắk Lắk\",\n          \"transport\": \"Đi bộ trong khu vực cụm thác.\",\n          \"price\": \"150.000 - 200.000 VNĐ/người (chi phí ăn trưa)\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"activity\": \"Tiếp tục hành trình trekking ngắn sang Thác Dray Sáp lân cận, chiêm ngưỡng dòng thác khói huyền thoại và khám phá hệ sinh thái rừng đặc dụng.\",\n          \"address\": \"Huyện Krông Ana, Đắk Lắk\",\n          \"transport\": \"Đi bộ xuyên rừng qua cầu treo kết nối hoặc di chuyển xe máy/ô tô khoảng 5 phút giữa hai khu vực thác.\",\n          \"price\": \"40.000 VNĐ/người (vé vào cổng Thác Dray Sáp)\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"activity\": \"Di chuyển về lại trung tâm TP. Buôn Ma Thuột, mua sắm quà lưu niệm (cà phê, đồ thổ cẩm) và kết thúc chuyến hành trình 2 ngày 1 đêm.\",\n          \"address\": \"\",\n          \"transport\": \"Di chuyển bằng ô tô hoặc xe máy khoảng 50 phút (~30km) để về lại thành phố.\",\n          \"price\": \"100.000 - 300.000 VNĐ/người (chi phí mua quà và ăn uống nhẹ trước khi ra sân bay/bến xe)\"\n        }\n      ]\n    }\n  ]\n}', '2026-07-06 07:43:26'),
(6, 2, 'Lịch trình 2 ngày - văn hoá, ẩm thực', 2, 'văn hoá, ẩm thực', '{\n  \"itinerary\": [\n    {\n      \"day\": 1,\n      \"title\": \"Khám phá Văn hóa Cà phê và Buôn làng Ê Đê\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"activity\": \"Bắt đầu ngày mới với trải nghiệm văn hóa cà phê đặc trưng của Buôn Ma Thuột. Thưởng thức cà phê tại một quán cà phê địa phương, tìm hiểu về quy trình sản xuất và lịch sử cà phê Buôn Ma Thuột. Bạn có thể ghé thăm Bảo tàng Cà phê Thế giới để có cái nhìn sâu sắc hơn.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng taxi hoặc xe máy trong trung tâm thành phố.\",\n          \"price\": \"50.000 - 150.000 VNĐ/người (bao gồm đồ uống và vé tham quan bảo tàng nếu có)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"activity\": \"Thưởng thức ẩm thực địa phương với các món ăn đặc sản Đắk Lắk như bún đỏ, phở khô hoặc nem nướng tại một nhà hàng ở trung tâm Buôn Ma Thuột.\",\n          \"address\": \"\",\n          \"transport\": \"Di chuyển bằng taxi hoặc xe máy trong trung tâm thành phố.\",\n          \"price\": \"50.000 - 100.000 VNĐ/người\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"activity\": \"Tham quan Buôn Akô Dhông, buôn làng Ê Đê cổ kính và đẹp nhất Buôn Ma Thuột. Tìm hiểu về kiến trúc nhà dài truyền thống, văn hóa và phong tục tập quán của người Ê Đê.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng xe máy hoặc taxi khoảng 15 phút (~5km) từ trung tâm thành phố.\",\n          \"price\": \"Miễn phí (có thể phát sinh chi phí mua sắm quà lưu niệm)\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"activity\": \"Ăn tối tại một nhà hàng có không gian ấm cúng ở Buôn Ma Thuột và khám phá chợ đêm để mua sắm đặc sản địa phương hoặc quà lưu niệm.\",\n          \"address\": \"\",\n          \"transport\": \"Di chuyển bằng taxi hoặc xe máy trong trung tâm thành phố.\",\n          \"price\": \"100.000 - 200.000 VNĐ/người\"\n        }\n      ]\n    },\n    {\n      \"day\": 2,\n      \"title\": \"Trải nghiệm Văn hóa Voi và Cảnh đẹp Hồ Lắk\",\n      \"items\": [\n        {\n          \"time\": \"Sáng\",\n          \"activity\": \"Khám phá Buôn Đôn, một làng văn hóa nổi tiếng với nghề săn bắt và thuần dưỡng voi. Bạn có thể tham quan nhà dài cổ, cầu treo và tìm hiểu về cuộc sống của người dân địa phương. Lưu ý: các hoạt động cưỡi voi đang dần được thay thế bằng các hoạt động thân thiện với voi hơn như cho voi ăn, tắm cho voi.\",\n          \"address\": \"Huyện Buôn Đôn, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng xe máy hoặc ô tô tự lái khoảng 1 giờ (~45km) từ trung tâm Buôn Ma Thuột.\",\n          \"price\": \"100.000 - 300.000 VNĐ/người (bao gồm vé vào cổng và các hoạt động trải nghiệm tại Buôn Đôn)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"activity\": \"Ăn trưa tại nhà hàng địa phương ở Buôn Đôn hoặc trên đường đi Hồ Lắk, thưởng thức các món ăn mang đậm hương vị núi rừng Tây Nguyên.\",\n          \"address\": \"\",\n          \"transport\": \"Di chuyển bằng xe máy hoặc ô tô.\",\n          \"price\": \"80.000 - 150.000 VNĐ/người\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"activity\": \"Tham quan Hồ Lắk, hồ nước ngọt tự nhiên lớn thứ 2 Việt Nam, gắn liền với văn hóa M\'nông. Bạn có thể trải nghiệm đi thuyền độc mộc trên hồ, ngắm cảnh hoàng hôn và thăm quan các buôn làng quanh hồ.\",\n          \"address\": \"Huyện Lắk, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng xe máy hoặc ô tô tự lái khoảng 1.5 - 2 giờ (~50km) từ Buôn Đôn hoặc khoảng 1.5 giờ (~50km) từ Buôn Ma Thuột. Nên đi theo quốc lộ 27.\",\n          \"price\": \"50.000 - 200.000 VNĐ/người (bao gồm vé vào cổng và chi phí thuê thuyền độc mộc nếu có)\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"activity\": \"Ăn tối và nghỉ ngơi tại các homestay hoặc nhà nghỉ ven Hồ Lắk để tận hưởng không khí trong lành và yên bình của vùng đất này. Thưởng thức các món cá nước ngọt đặc sản của hồ.\",\n          \"address\": \"\",\n          \"transport\": \"Đi bộ hoặc di chuyển xe máy/ô tô ngắn trong khu vực Hồ Lắk.\",\n          \"price\": \"150.000 - 300.000 VNĐ/người (bao gồm bữa tối, chưa bao gồm chi phí lưu trú)\"\n        }\n      ]\n    }\n  ]\n}', '2026-07-06 08:02:51'),
(7, 2, 'Lịch trình 4 ngày - ẩm thực, trekking', 4, 'ẩm thực, trekking', '{\n  \"itinerary\": [\n    {\n      \"day\": 1,\n      \"title\": \"Khám phá Văn hóa Cà phê và Buôn làng Ê Đê\",\n      \"items\": [\n        {\n          \"time\": \"Sáng sớm\",\n          \"activity\": \"Thưởng thức cà phê Buôn Ma Thuột tại một quán cà phê địa phương, tìm hiểu về văn hóa cà phê\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng taxi hoặc xe máy đến các quán cà phê trung tâm TP Buôn Ma Thuột.\",\n          \"price\": \"50.000 - 100.000 VNĐ/người (cho đồ uống và đồ ăn nhẹ)\"\n        },\n        {\n          \"time\": \"Sáng\",\n          \"activity\": \"Tham quan Buôn Akô Dhông, buôn làng Ê Đê truyền thống với những ngôi nhà dài cổ kính.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Từ trung tâm thành phố, di chuyển bằng xe máy hoặc taxi khoảng 15 phút (~5km).\",\n          \"price\": \"Miễn phí (có thể phát sinh chi phí mua quà lưu niệm)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"activity\": \"Thưởng thức ẩm thực địa phương tại TP. Buôn Ma Thuột (ví dụ: bún đỏ, nem nướng).\",\n          \"address\": \"\",\n          \"transport\": \"Đi bộ hoặc di chuyển bằng taxi/xe máy đến các nhà hàng/quán ăn địa phương.\",\n          \"price\": \"50.000 - 150.000 VNĐ/người\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"activity\": \"Tìm hiểu sâu hơn về cà phê tại Bảo tàng Cà phê Thế giới hoặc một nông trại cà phê gần trung tâm thành phố.\",\n          \"address\": \"TP. Buôn Ma Thuột, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng xe máy hoặc taxi trong TP Buôn Ma Thuột.\",\n          \"price\": \"Miễn phí (tại các quán cà phê), 75.000 VNĐ/người (vé vào Bảo tàng Cà phê Thế giới)\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"activity\": \"Khám phá chợ đêm Buôn Ma Thuột và thưởng thức ẩm thực đường phố.\",\n          \"address\": \"\",\n          \"transport\": \"Đi bộ hoặc xe máy/taxi trong TP Buôn Ma Thuột.\",\n          \"price\": \"100.000 - 200.000 VNĐ/người\"\n        }\n      ]\n    },\n    {\n      \"day\": 2,\n      \"title\": \"Trekking Thác Nước Hùng Vĩ\",\n      \"items\": [\n        {\n          \"time\": \"Sáng sớm\",\n          \"activity\": \"Trekking và khám phá Thác Dray Nur, một trong những thác nước đẹp nhất Tây Nguyên.\",\n          \"address\": \"Huyện Krông Ana, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng xe máy hoặc ô tô tự lái khoảng 1 giờ (~30km) từ trung tâm Buôn Ma Thuột.\",\n          \"price\": \"30.000 VNĐ/người (vé vào cổng)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"activity\": \"Ăn trưa dã ngoại hoặc tại nhà hàng địa phương gần thác Dray Nur.\",\n          \"address\": \"\",\n          \"transport\": \"Di chuyển gần khu vực thác.\",\n          \"price\": \"100.000 - 200.000 VNĐ/người\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"activity\": \"Tiếp tục trekking và khám phá Thác Dray Sáp, chiêm ngưỡng \'nước khói\' huyền ảo.\",\n          \"address\": \"Huyện Krông Ana, Đắk Lắk\",\n          \"transport\": \"Thác Dray Sáp và Dray Nur nằm gần nhau, có thể đi bộ qua cầu hoặc di chuyển bằng xe máy/ô tô một đoạn ngắn.\",\n          \"price\": \"30.000 VNĐ/người (vé vào cổng)\"\n        },\n        {\n          \"time\": \"Hoàng hôn\",\n          \"activity\": \"Ngắm hoàng hôn tại khu vực thác nước hoặc trên đường về Buôn Ma Thuột.\",\n          \"address\": \"\",\n          \"transport\": \"Trên đường về trung tâm thành phố.\",\n          \"price\": \"Miễn phí\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"activity\": \"Ăn tối tại Buôn Ma Thuột và nghỉ ngơi.\",\n          \"address\": \"\",\n          \"transport\": \"Di chuyển bằng taxi/xe máy.\",\n          \"price\": \"100.000 - 250.000 VNĐ/người\"\n        }\n      ]\n    },\n    {\n      \"day\": 3,\n      \"title\": \"Khám phá Văn hóa Voi và Thiên nhiên Rừng\",\n      \"items\": [\n        {\n          \"time\": \"Sáng sớm\",\n          \"activity\": \"Khám phá Vườn quốc gia Yok Đôn, trekking rừng và tìm hiểu về voi rừng.\",\n          \"address\": \"Huyện Buôn Đôn, Đắk Lắk\",\n          \"transport\": \"Di chuyển bằng xe máy hoặc ô tô tự lái khoảng 1.5 giờ (~40km) từ Buôn Ma Thuột.\",\n          \"price\": \"40.000 - 150.000 VNĐ/người (vé vào cổng và các hoạt động như đi bộ/trekking)\"\n        },\n        {\n          \"time\": \"Trưa\",\n          \"activity\": \"Ăn trưa với các món ăn đặc sản tại Buôn Đôn.\",\n          \"address\": \"\",\n          \"transport\": \"Di chuyển từ Vườn quốc gia Yok Đôn đến các nhà hàng ở Buôn Đôn.\",\n          \"price\": \"150.000 - 250.000 VNĐ/người\"\n        },\n        {\n          \"time\": \"Chiều\",\n          \"activity\": \"Tham quan Buôn Đôn, tìm hiểu về văn hóa săn bắt và thuần dưỡng voi, khám phá cầu treo.\",\n          \"address\": \"Huyện Buôn Đôn, Đắk Lắk\",\n          \"transport\": \"Di chuyển trong khu vực Buôn Đôn.\",\n          \"price\": \"20.000 - 50.000 VNĐ/người (vé vào cổng, phí cầu treo), có thể phát sinh chi phí cho các dịch vụ khác.\"\n        },\n        {\n          \"time\": \"Hoàng hôn\",\n          \"activity\": \"Ngắm cảnh hoàng hôn tại Buôn Đôn hoặc trên đường về Buôn Ma Thuột.\",\n          \"address\": \"\",\n          \"transport\": \"Trên đường về trung tâm thành phố.\",\n          \"price\": \"Miễn phí\"\n        },\n        {\n          \"time\": \"Tối\",\n          \"activity\": \"Thưởng thức bữa tối đặc sản tại Buôn Ma Thuột, thư giãn.\",\n          \"address\": \"\",\n          \"transport\": \"Di chuyển bằng taxi/xe máy.\",\n          \"price\": \"100.000 - 250.000 VNĐ/người\"\n        }\n      ]\n    },\n    {\n      \"day\": 4,\n      \"title\": \"Hồ Lắk và Văn hóa M\'nông\",\n      \"items\": [\n        {\n          \"time\": \"Sáng sớm\",\n          \"activity\": \"Di chuyển đến Hồ Lắk, ngắm bình mi