(186, 19, NULL, 2, 'Sáng', 'Khám phá Thác Dray Nur, một trong những thác nước hùng vĩ nhất Tây Nguyên, chụp ảnh và tận hưởng không khí trong lành.', 'Huyện Krông Ana, Đắk Lắk', 'Nên thuê xe máy hoặc taxi đi khoảng 45 phút (~30km) theo quốc lộ 27.', 4),
(187, 19, NULL, 2, 'Trưa', 'Ăn trưa tại khu vực gần thác.', '', 'Đi bộ hoặc xe máy.', 5),
(188, 19, NULL, 2, 'Chiều', 'Tham quan Hồ Lắk, hồ nước ngọt tự nhiên lớn thứ 2 Việt Nam, trải nghiệm đi thuyền độc mộc và tìm hiểu văn hoá M\'nông.', 'Huyện Lắk, Đắk Lắk', 'Di chuyển bằng xe máy hoặc taxi khoảng 1 giờ (~50km) từ Thác Dray Nur hoặc TP Buôn Ma Thuột.', 6),
(189, 19, NULL, 2, 'Tối', 'Ăn tối và mua sắm đặc sản Đắk Lắk trước khi kết thúc chuyến đi.', '', 'Di chuyển về Buôn Ma Thuột bằng xe máy hoặc taxi.', 7),
(190, 20, NULL, 1, 'Sáng sớm', 'Trải nghiệm văn hóa Cà phê Buôn Ma Thuột tại một quán cà phê địa phương để bắt đầu ngày mới.', 'TP. Buôn Ma Thuột, Đắk Lắk', 'Thuê xe máy hoặc taxi để di chuyển trong thành phố.', 0),
(191, 20, NULL, 1, 'Sáng', 'Tham quan Buôn Akô Dhông - buôn làng Ê Đê đẹp nhất Buôn Ma Thuột, tìm hiểu kiến trúc nhà dài và văn hóa địa phương.', 'TP. Buôn Ma Thuột, Đắk Lắk', 'Đi xe máy hoặc taxi khoảng 15 phút từ trung tâm thành phố.', 1),
(192, 20, NULL, 1, 'Trưa', 'Thưởng thức ẩm thực địa phương tại Buôn Ma Thuột.', '', 'Di chuyển bằng xe máy hoặc đi bộ đến các quán ăn.', 2),
(193, 20, NULL, 1, 'Chiều', 'Tham quan Hồ Ea Kao, tận hưởng không khí trong lành và cảnh hoàng hôn lãng mạn.', 'TP. Buôn Ma Thuột, Đắk Lắk', 'Di chuyển bằng xe máy hoặc taxi khoảng 20 phút từ trung tâm thành phố.', 3),
(194, 20, NULL, 1, 'Tối', 'Dùng bữa tối tại Buôn Ma Thuột và khám phá các quán cà phê buổi tối.', '', 'Thuê xe máy hoặc taxi.', 4),
(195, 20, NULL, 2, 'Sáng sớm', 'Ngắm bình minh và tham quan Hồ Lắk, hồ nước ngọt tự nhiên lớn thứ 2 Việt Nam, khám phá văn hóa M\'nông.', 'Huyện Lắk, Đắk Lắk', 'Nên thuê xe máy hoặc taxi đi khoảng 1 tiếng (~50km) theo quốc lộ 27.', 5),
(196, 20, NULL, 2, 'Trưa', 'Ăn trưa với đặc sản địa phương gần Hồ Lắk hoặc trên đường về Buôn Ma Thuột.', '', 'Di chuyển bằng xe máy hoặc taxi.', 6),
(197, 20, NULL, 2, 'Chiều', 'Tham quan Thác Dray Nur, một trong những thác nước hùng vĩ nhất Tây Nguyên, để chụp ảnh và tận hưởng thiên nhiên.', 'Huyện Krông Ana, Đắk Lắk', 'Từ Hồ Lắk, di chuyển bằng xe máy hoặc taxi khoảng 1 giờ 30 phút (~70km).', 7),
(198, 20, NULL, 2, 'Tối', 'Quay về Buôn Ma Thuột, ăn tối và mua sắm quà lưu niệm trước khi kết thúc chuyến đi.', '', 'Di chuyển bằng xe máy hoặc taxi về Buôn Ma Thuột (~30 phút từ thác Dray Nur).', 8),
(199, 21, NULL, 1, 'Sáng', 'Trải nghiệm văn hóa cà phê Buôn Ma Thuột tại Làng cà phê Trung Nguyên', 'TP. Buôn Ma Thuột, Đắk Lắk', 'Thuê xe máy hoặc taxi/Grab để di chuyển đến Làng cà phê Trung Nguyên. Thời gian di chuyển tùy thuộc vào vị trí khách sạn.', 0),
(200, 21, NULL, 1, 'Trưa', 'Tham quan Buôn Akô Dhông - Buôn làng Ê Đê cổ kính', 'TP. Buôn Ma Thuột, Đắk Lắk', 'Di chuyển bằng xe máy hoặc taxi/Grab từ trung tâm thành phố (khoảng 15 phút).', 1),
