(202, 21, NULL, 1, 'Tối', 'Thưởng thức ẩm thực và cà phê tại quán địa phương', '', 'Di chuyển bằng xe máy hoặc taxi/Grab trong nội thành.', 3),
(203, 21, NULL, 2, 'Sáng', 'Khám phá Thác Dray Nur - Thác nước hùng vĩ bậc nhất Tây Nguyên', 'Huyện Krông Ana, Đắk Lắk', 'Thuê xe máy hoặc taxi/Grab đi khoảng 45 phút (~30km) theo quốc lộ 14 và đường tỉnh 682.', 4),
