(205, 21, NULL, 2, 'Chiều', 'Trải nghiệm Hồ Ea Kao và thư giãn', 'TP. Buôn Ma Thuột, Đắk Lắk', 'Di chuyển bằng xe máy hoặc taxi/Grab từ Thác Dray Nur về Hồ Ea Kao (khoảng 30-40 phút).', 6),
(206, 21, NULL, 2, 'Tối', 'Mua sắm quà lưu niệm và thưởng thức bữa tối cuối cùng', '', 'Di chuyển bằng xe máy hoặc taxi/Grab trong nội thành.', 7),
(207, 22, NULL, 1, 'Sáng', 'Tham quan Thác Dray Nur và Thác Dray Sáp, chiêm ngưỡng vẻ đẹp thiên nhiên hùng vĩ và chụp ảnh.', 'Huyện Krông Ana, Đắk Lắk', 'Thuê xe máy hoặc taxi/Grab đi khoảng 30km (~45 phút) từ trung tâm Buôn Ma Thuột theo QL14 rồi rẽ vào đường 682. Chi phí thuê xe máy khoảng 100.000 - 150.000 VNĐ/ngày.', 0),
