(211, 22, NULL, 2, 'Sáng', 'Khám phá Hồ Lắk, hồ nước ngọt tự nhiên lớn thứ 2 Việt Nam, trải nghiệm thuyền độc mộc và văn hóa M\'nông.', 'Huyện Lắk, Đắk Lắk', 'Thuê xe máy hoặc taxi/Grab đi khoảng 50km (~1 tiếng 15 phút) theo quốc lộ 27 từ Buôn Ma Thuột.', 4),
(212, 22, NULL, 2, 'Trưa', 'Ăn trưa tại Hồ Lắk với các món ăn địa phương và nghỉ ngơi.', '', 'Đi bộ hoặc xe máy/taxi quanh khu vực Hồ Lắk.', 5),
(213, 22, NULL, 2, 'Chiều', 'Tham quan Buôn Akô Dhông, buôn làng Ê Đê đẹp nhất Buôn Ma Thuột, tìm hiểu kiến trúc nhà dài và văn hóa bản địa.', 'TP. Buôn Ma Thuột, Đắk Lắk', 'Di chuyển bằng xe máy hoặc taxi/Grab về Buôn Ma Thuột (~1h15p), sau đó đi bộ hoặc xe máy/taxi trong thành phố đến Buôn Akô Dhông.', 6),
(214, 22, NULL, 2, 'Tối', 'Ăn tối và chuẩn bị kết thúc hành trình.', '', 'Di chuyển bằng xe máy hoặc taxi/Grab trong thành phố.', 7),
(215, 23, NULL, 1, 'Sáng', 'Đón bình minh tại Hồ Lắk và trải nghiệm đi thuyền độc mộc trên hồ. Khám phá làng M\'nông và tìm hiểu văn hóa bản địa.', 'Huyện Lắk, Đắk Lắk', 'Thuê xe máy hoặc taxi/ô tô riêng để di chuyển từ Buôn Ma Thuột đến Hồ Lắk.', 0),
