(231, 24, NULL, 2, 'Sáng', 'Di chuyển đến Hồ Lắk, hồ nước ngọt tự nhiên lớn thứ 2 Việt Nam. Trải nghiệm đi thuyền độc mộc trên hồ và tìm hiểu văn hóa M\'nông.', 'Huyện Lắk, Đắk Lắk', 'Thuê xe máy (khoảng 1.5 - 2 tiếng di chuyển từ BMT) hoặc thuê xe ô tô riêng.', 4),
(232, 24, NULL, 2, 'Trưa', 'Ăn trưa đặc sản tại khu vực Hồ Lắk.', 'Huyện Lắk, Đắk Lắk', 'Đi bộ hoặc xe máy trong phạm vi gần.', 5);
