(381, 36, 5, 1, 'Sáng sớm', 'Khám phá Vườn Quốc gia Yok Đôn - Trekking và chụp ảnh hệ sinh thái rừng. Du khách sẽ có cơ hội ngắm bình minh trong rừng, tìm hiểu về đa dạng sinh học và có thể bắt gặp các loài động vật hoang dã (từ xa).', 'Huyện Buôn Đôn, Đắk Lắk', 'Thuê xe máy (khoảng 150.000đ/ngày) hoặc taxi/Grab từ Buôn Ma Thuột đến Yok Đôn (khoảng 40km). Di chuyển bằng xe jeep trong vườn quốc gia để đến các điểm trekking.', 0),
(382, 36, NULL, 1, 'Trưa', 'Ăn trưa đặc sản Tây Nguyên và nghỉ ngơi tại Buôn Ma Thuột.', '140 Lê Thánh Tông, TP. Buôn Ma Thuột, Đắk Lắk (Quán Cà Te)', 'Xe máy hoặc taxi/Grab.', 1),
(383, 36, 16, 1, 'Chiều', 'Tham quan Núi Đá Voi Mẹ và chụp ảnh hoàng hôn tại Hồ Lắk. Đây là cơ hội tuyệt vời để chụp những bức ảnh độc đáo với cảnh quan thiên nhiên hùng vĩ và ánh sáng hoàng hôn.', 'Lắk, Đắk Lắk', 'Xe máy hoặc ô tô cá nhân từ Buôn Ma Thuột đến Đá Voi Mẹ (khoảng 50km). Từ Đá Voi Mẹ di chuyển khoảng 15km đến Hồ Lắk.', 2),
(384, 36, 1, 1, 'Tối', 'Thưởng thức ẩm thực địa phương bên Hồ Lắk và trải nghiệm văn hóa M\'nông.', 'Huyện Lắk, Đắk Lắk', 'Di chuyển bộ hoặc xe máy đến các nhà hàng ven hồ. Di chuyển đến chỗ lưu trú.', 3),
(385, 36, 1, 2, 'Sáng sớm', 'Đón bình minh trên Hồ Lắk, trải nghiệm chèo thuyền độc mộc và khám phá văn hóa M\'nông. Đây là cơ hội tuyệt vời để chụp những bức ảnh bình minh huyền ảo trên mặt hồ.', 'Huyện Lắk, Đắk Lắk', 'Đi bộ hoặc xe máy đến bờ hồ.', 4),
(386, 36, NULL, 2, 'Trưa', 'Di chuyển về Buôn Ma Thuột, ăn trưa và nghỉ ngơi.', 'Ngã 4 Phan Đình Giót - Lê Hồng Phong, TP. Buôn Ma Thuột, Đắk Lắk (Bún đỏ cô Thu)', 'Xe máy hoặc ô tô cá nhân từ Hồ Lắk về Buôn Ma Thuột (khoảng 50km).', 5),
(387, 36, 2, 2, 'Chiều', 'Tham quan Thác Dray Nur và Thác Dray Sáp, trải nghiệm trekking nhẹ và chụp ảnh tại một trong những thác nước hùng vĩ nhất Tây Nguyên.', 'Huyện Krông Ana, Đắk Lắk', 'Xe máy hoặc taxi/Grab từ Buôn Ma Thuột đến Thác Dray Nur (khoảng 25km). Có cầu nối sang Thác Dray Sáp.', 6),
