(523, 48, 6, 2, 'Chiều', 'Khám phá văn hóa cà phê Buôn Ma Thuột, thưởng thức cà phê và mua sắm đặc sản.', 'TP. Buôn Ma Thuột, Đắk Lắk', 'Xe máy hoặc taxi trong thành phố.', 6),
(524, 48, NULL, 2, 'Tối', 'Ăn tối và dạo phố Buôn Ma Thuột.', 'TP. Buôn Ma Thuột, Đắk Lắk', 'Đi bộ hoặc taxi trong thành phố.', 7),
(525, 48, 4, 3, 'Sáng', 'Thăm Buôn Đôn, tìm hiểu văn hóa săn bắt và thuần dưỡng voi, khám phá nhà dài truyền thống và cầu treo.', 'Huyện Buôn Đôn, Đắk Lắk', 'Thuê xe máy hoặc taxi/ô tô từ Buôn Ma Thuột đến Buôn Đôn (~40km).', 8),
(526, 48, NULL, 3, 'Trưa', 'Ăn trưa tại Buôn Đôn hoặc quay về Buôn Ma Thuột.', 'Huyện Buôn Đôn, Đắk Lắk', 'Đi bộ hoặc xe cá nhân.', 9),
(527, 48, 7, 3, 'Chiều', 'Tham quan Buôn Akô Dhông, buôn làng Ê Đê lâu đời và đẹp nhất Buôn Ma Thuột.', 'TP. Buôn Ma Thuột, Đắk Lắk', 'Xe máy hoặc taxi trong thành phố.', 10),
(528, 48, NULL, 3, 'Tối', 'Ăn tối, mua sắm quà lưu niệm và kết thúc chuyến đi.', 'TP. Buôn Ma Thuột, Đắk Lắk', 'Đi bộ hoặc taxi trong thành phố.', 11);
