(1, 'Hồ Lắk', 'Lak Lake', 'Khám phá vẻ đẹp Hồ Lắk qua góc nhìn 360 độ.', 'Explore the beauty of Lak Lake through a 360 degree view.', 'https://pannellum.org/images/alma.jpg', 'https://pannellum.org/images/alma.jpg', NULL, '2026-07-09 08:04:13'),
(2, 'Thác Dray Nur', 'Dray Nur Waterfall', 'Trải nghiệm sự hùng vĩ của Thác Dray Nur.', 'Experience the majesty of Dray Nur Waterfall.', 'https://pannellum.org/images/cerro-toco-0.jpg', 'https://pannellum.org/images/cerro-toco-0.jpg', NULL, '2026-07-09 08:04:13'),
(3, 'Buôn Đôn', 'Buon Don', 'Góc nhìn toàn cảnh Buôn Đôn truyền thống.', 'A panoramic view of traditional Buon Don.', 'https://pannellum.org/images/bma-0.jpg', 'https://pannellum.org/images/bma-0.jpg', NULL, '2026-07-09 08:04:13');
