(9, 8, 'scene_main_8', 'Hồ Ea Kao', 'Ea Kao Lake', 'Trải nghiệm không gian 360 độ tại Hồ Ea Kao (Ảnh mẫu demo)', 'Experience a 360-degree view at Ea Kao Lake.', 'http://localhost/du_an_mau-Hieus/du_an_mau-An/main/assets/images/360/lak_lake_360.png', NULL, NULL, 0.00, 0.00, 110, 0, 1, '2026-07-09 08:33:20'),
(10, 9, 'scene_9_1', 'Gành Đá Đĩa - Phú Yên - Toàn cảnh', 'Ganh Da Dia - Panorama', 'Trải nghiệm ngắm nhìn toàn cảnh 360 độ tuyệt đẹp tại Gành Đá Đĩa.', 'Experience a stunning 360-degree view of Ganh Da Dia.', 'http://localhost/travel_daklak/assets/images/360/ganh_da_dia_360.png', 'http://localhost/travel_daklak/assets/images/360/ganh_da_dia_360.png', NULL, 0.00, 0.00, 110, 1, 1, '2026-07-22 07:13:10'),
(11, 10, 'scene_10_1', 'Đầm Ô Loan - Toàn cảnh', 'Dam O Loan - Panorama', 'Chiêm ngưỡng hoàng hôn 360 độ tại Đầm Ô Loan thanh bình.', 'Enjoy a 360-degree sunset view of the calm Dam O Loan lagoon.', 'http://localhost/travel_daklak/assets/images/360/o_loan_360.png', 'http://localhost/travel_daklak/assets/images/360/o_loan_360.png', NULL, 0.00, 0.00, 110, 1, 1, '2026-07-22 07:13:10'),
(12, 11, 'scene_11_1', 'Vịnh Vũng Rô - Toàn cảnh', 'Vung Ro Bay - Panorama', 'Khám phá không gian bao la 360 độ của Vịnh Vũng Rô.', 'Discover the beautiful 360-degree scenery of Vung Ro Bay.', 'http://localhost/travel_daklak/assets/images/360/vung_ro_360.png', 'http://localhost/travel_daklak/assets/images/360/vung_ro_360.png', NULL, 0.00, 0.00, 110, 1, 1, '2026-07-22 07:13:10'),
(13, 12, 'scene_12_1', 'Bãi Môn - Mũi Điện - Toàn cảnh', 'Bai Mon - Mui Dien - Panorama', 'Ngắm nhìn Bãi Môn và ngọn hải đăng Mũi Điện từ góc nhìn 360 độ.', 'Explore Bai Mon beach and Mui Dien lighthouse in 360 degrees.', 'http://localhost/travel_daklak/assets/images/360/mui_dien_360.png', 'http://localhost/travel_daklak/assets/images/360/mui_dien_360.png', NULL, 0.00, 0.00, 110, 1, 1, '2026-07-22 07:13:10'),
(14, 13, 'scene_13_1', 'Tháp Nghinh Phong - Toàn cảnh', 'Nghinh Phong Tower - Panorama', 'Chiêm ngưỡng kiến trúc độc đáo của Tháp Nghinh Phong sát bờ biển.', 'Admire the modern architecture of Nghinh Phong Tower by the sea.', 'http://localhost/travel_daklak/assets/images/360/nghinh_phong_360.png', 'http://localhost/travel_daklak/assets/images/360/nghinh_phong_360.png', NULL, 0.00, 0.00, 110, 1, 1, '2026-07-22 07:13:10'),
(15, 14, 'scene_14_1', 'Hòn Yến - Toàn cảnh', 'Hon Yen - Panorama', 'Ngắm nhìn rạn san hô tuyệt đẹp tại Hòn Yến từ trên cao.', 'View the colorful coral reefs of Hon Yen island from above.', 'http://localhost/travel_daklak/assets/images/360/hon_yen_360.png', 'http://localhost/travel_daklak/assets/images/360/hon_yen_360.png', NULL, 0.00, 0.00, 110, 1, 1, '2026-07-22 07:13:10'),
(16, 15, 'scene_15_1', 'Thác Thủy Tiên - Toàn cảnh', 'Thuy Tien Waterfall - Panorama', 'Trải nghiệm không gian 360 độ tại Thác Thủy Tiên giữa rừng xanh.', 'Experience a multi-tiered waterfall in the lush green jungle.', 'http://localhost/travel_daklak/assets/images/360/thuy_tien_360.png', 'http://localhost/travel_daklak/assets/images/360/thuy_tien_360.png', NULL, 0.00, 0.00, 110, 1, 1, '2026-07-22 07:13:10'),
(17, 16, 'scene_16_1', 'Núi Đá Voi Mẹ - Toàn cảnh', 'Elephant Rock - Panorama', 'Chiêm ngưỡng toàn cảnh Núi Đá Voi Mẹ khổng lồ giữa thiên nhiên.', 'See the massive elephant-shaped granite rock from a 360-degree view.', 'http://localhost/travel_daklak/assets/images/360/da_voi_me_360.png', 'http://localhost/travel_daklak/assets/images/360/da_voi_me_360.png', NULL, 0.00, 0.00, 110, 1, 1, '2026-07-22 07:13:10');
